import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float h2f(__half h) { return __half2float(h); }
__device__ __forceinline__ __half f2h(float f) { return __float2half(f); }

// Compile-time tile sizes.
constexpr int BLOCK_M = 32;   // rows of Q processed per CTA
constexpr int BLOCK_D = 32;   // chunk of head-dim processed at a time
constexpr int THREADS = 256;  // threads per block
constexpr int MAX_ACC = 64;   // upper bound of (BLOCK_M*N)/THREADS per thread

__global__ void attention_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    float scale)
{
    int b = blockIdx.z;
    int h = blockIdx.y;
    int m_tile = blockIdx.x;
    int m_base = m_tile * BLOCK_M;

    int64_t bh_stride = (int64_t)N * D;
    int64_t bh_idx = (int64_t)b * H + h;

    const __half* Qptr = Q + bh_idx * bh_stride;
    const __half* Kptr = K + bh_idx * bh_stride;
    const __half* Vptr = V + bh_idx * bh_stride;
    __half* Optr = O + bh_idx * bh_stride;

    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));

    extern __shared__ unsigned char smem_raw[];
    __half* Qs_buf0  = reinterpret_cast<__half*>(smem_raw);
    __half* Qs_buf1  = Qs_buf0 + BLOCK_M * BLOCK_D;
    __half* KVs_buf0 = Qs_buf1 + BLOCK_M * BLOCK_D;
    __half* KVs_buf1 = KVs_buf0 + (size_t)N * BLOCK_D;
    float*  S_ptr    = reinterpret_cast<float*>(KVs_buf1 + (size_t)N * BLOCK_D);
    auto sS  = make_tensor(make_smem_ptr(S_ptr),   make_shape(Int<BLOCK_M>{}, N), make_stride(N, Int<1>{}));
    __half* Qbuf[2] = { Qs_buf0, Qs_buf1 };
    __half* Kbuf[2] = { KVs_buf0, KVs_buf1 };
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int total_s_elems = BLOCK_M * N;
    int elems_per_thread_s = total_s_elems / nthreads;
    float acc[MAX_ACC];
    #pragma unroll
    for (int i = 0; i < MAX_ACC; ++i) acc[i] = 0.0f;
    int num_dchunks = D / BLOCK_D;
    int qelems2 = (BLOCK_M * BLOCK_D) / 2;
    const __half2* Qptr2 = reinterpret_cast<const __half2*>(Qptr);
    int kelems2 = (N * BLOCK_D) / 2;
    const __half2* Kptr2 = reinterpret_cast<const __half2*>(Kptr);
    auto load_qk_chunk = [&](int c, int buf) {
        int d0 = c * BLOCK_D;
        __half2* Qs2 = reinterpret_cast<__half2*>(Qbuf[buf]);
        for (int idx = tid; idx < qelems2; idx += nthreads) {
            int m = idx / (BLOCK_D / 2);
            int dl2 = idx % (BLOCK_D / 2);
            int gidx = ((m_base + m) * D + d0) / 2 + dl2;
            Qs2[m * (BLOCK_D / 2) + dl2] = Qptr2[gidx];
        }
        __half2* KVs2 = reinterpret_cast<__half2*>(Kbuf[buf]);
        for (int idx = tid; idx < kelems2; idx += nthreads) {
            int n = idx / (BLOCK_D / 2);
            int dl2 = idx % (BLOCK_D / 2);
            int gidx = (n * D + d0) / 2 + dl2;
            KVs2[n * (BLOCK_D / 2) + dl2] = Kptr2[gidx];
        }
    };
    // ---- Pass 1: S = Q @ K^T (accumulated over head-dim chunks, double-buffered) ----
    int cur = 0;
    load_qk_chunk(0, cur);
    __syncthreads();
    for (int c = 0; c < num_dchunks; ++c) {
        int nxt = 1 - cur;
        if (c + 1 < num_dchunks) {
            load_qk_chunk(c + 1, nxt);
        }
        __half* Qs_ptr = Qbuf[cur];
        __half* KVs_ptr = Kbuf[cur];
        for (int i = 0; i < elems_per_thread_s && i < MAX_ACC; ++i) {
            int idx = tid + i * nthreads;
            if (idx >= total_s_elems) continue;
            int m = idx / N;
            int n = idx % N;
            const float4* qrow4 = reinterpret_cast<const float4*>(Qs_ptr + m * BLOCK_D);
            const float4* krow4 = reinterpret_cast<const float4*>(KVs_ptr + n * BLOCK_D);
            float sum = 0.0f;
            #pragma unroll
            for (int dl4 = 0; dl4 < BLOCK_D / 8; ++dl4) {
                float4 qv = qrow4[dl4];
                float4 kv = krow4[dl4];
                const __half2* q2 = reinterpret_cast<const __half2*>(&qv);
                const __half2* k2 = reinterpret_cast<const __half2*>(&kv);
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    float2 qf = __half22float2(q2[j]);
                    float2 kf = __half22float2(k2[j]);
                    sum += qf.x * kf.x + qf.y * kf.y;
                }
            }
            acc[i] += sum;
        }
        __syncthreads();
        cur = nxt;
    }
    for (int i = 0; i < elems_per_thread_s && i < MAX_ACC; ++i) {
        int idx = tid + i * nthreads;
        if (idx >= total_s_elems) continue;
        int m = idx / N;
        int n = idx % N;
        sS(m, n) = acc[i] * scale;
    }
    __syncthreads();
    // ---- Softmax over each row of S (warp-parallel reduction) ----
    int warp_id = tid / 32;
    int lane = tid % 32;
    int nwarps = nthreads / 32;
    for (int m = warp_id; m < BLOCK_M; m += nwarps) {
        float maxv = -1e30f;
        for (int n = lane; n < N; n += 32) {
            float v = sS(m, n);
            maxv = fmaxf(maxv, v);
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            maxv = fmaxf(maxv, __shfl_xor_sync(0xffffffff, maxv, offset));
        }
        float sumv = 0.0f;
        for (int n = lane; n < N; n += 32) {
            float e = expf(sS(m, n) - maxv);
            sS(m, n) = e;
            sumv += e;
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sumv += __shfl_xor_sync(0xffffffff, sumv, offset);
        }
        float inv = 1.0f / sumv;
        for (int n = lane; n < N; n += 32) {
            sS(m, n) = sS(m, n) * inv;
        }
    }
    __syncthreads();
    // ---- Pass 2: O = P @ V (double-buffered) ----
    int velems2 = (N * BLOCK_D) / 2;
    const __half2* Vptr2 = reinterpret_cast<const __half2*>(Vptr);
    int oelems4 = (BLOCK_M * BLOCK_D) / 8;
    auto load_v_chunk = [&](int c, int buf) {
        int d0 = c * BLOCK_D;
        __half2* KVs2v = reinterpret_cast<__half2*>(Kbuf[buf]);
        for (int idx = tid; idx < velems2; idx += nthreads) {
            int n = idx / (BLOCK_D / 2);
            int dl2 = idx % (BLOCK_D / 2);
            int gidx = (n * D + d0) / 2 + dl2;
            KVs2v[n * (BLOCK_D / 2) + dl2] = Vptr2[gidx];
        }
    };
    cur = 0;
    load_v_chunk(0, cur);
    __syncthreads();
    for (int c = 0; c < num_dchunks; ++c) {
        int nxt = 1 - cur;
        if (c + 1 < num_dchunks) {
            load_v_chunk(c + 1, nxt);
        }
        int d0 = c * BLOCK_D;
        __half* KVs_ptr = Kbuf[cur];
        for (int idx = tid; idx < oelems4; idx += nthreads) {
            int m = idx / (BLOCK_D / 8);
            int dl8 = idx % (BLOCK_D / 8);
            int dl = dl8 * 8;
            float sum[8];
            #pragma unroll
            for (int j = 0; j < 8; ++j) sum[j] = 0.0f;
            for (int n = 0; n < N; ++n) {
                float p = sS(m, n);
                float4 v4 = *reinterpret_cast<const float4*>(&KVs_ptr[n * BLOCK_D + dl]);
                const __half2* v2 = reinterpret_cast<const __half2*>(&v4);
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    float2 vf = __half22float2(v2[j]);
                    sum[2 * j] += p * vf.x;
                    sum[2 * j + 1] += p * vf.y;
                }
            }
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                mO(m_base + m, d0 + dl + j) = f2h(sum[j]);
            }
        }
        __syncthreads();
        cur = nxt;
    }
}

torch::Tensor cute_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(Q.dim() == 4, "expected 4D tensor [B,H,N,D]");

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int N = (int)Qc.size(2);
    int D = (int)Qc.size(3);

    TORCH_CHECK(N % BLOCK_M == 0, "seq len must be divisible by BLOCK_M(=32)");
    TORCH_CHECK(D % BLOCK_D == 0, "head dim must be divisible by BLOCK_D(=64)");
    TORCH_CHECK((BLOCK_M * N) % THREADS == 0, "BLOCK_M*N must be divisible by THREADS");
    TORCH_CHECK((BLOCK_M * N) / THREADS <= MAX_ACC, "sequence length too large for this kernel configuration");

    auto O = torch::empty_like(Qc);

    float scale = 1.0f / sqrtf((float)D);

    dim3 grid(N / BLOCK_M, H, B);
    dim3 block(THREADS);

    size_t smem_bytes = 2 * ((size_t)BLOCK_M * BLOCK_D + (size_t)N * BLOCK_D) * sizeof(__half)
                       + (size_t)BLOCK_M * N * sizeof(float);

    cudaError_t attrErr = cudaFuncSetAttribute(attention_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    TORCH_CHECK(attrErr == cudaSuccess, "cudaFuncSetAttribute failed (requested ", smem_bytes, " bytes dynamic shared mem): ", cudaGetErrorString(attrErr));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    attention_kernel<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
        B, H, N, D, scale
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "attention_kernel launch failed: ", cudaGetErrorString(err));

    return O;
}
"""

cute_attn_ext = load_inline(
    name="cute_attention_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_attention_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_attn_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_attention_forward(Q, K, V)

