import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
