                }
            }
            acc[i] += sum;
        }
        __syncthreads();
        cur = nxt;
    }
    for (int i = 0; i < elems_per_thread_s && i < MAX_ACC; ++i) {
        int idx = tid + i * nthreads;
        if (idx >= total_s_elems) continue;
