__device__ __forceinline__ float h2f(__half h) { return __half2float(h); }
__device__ __forceinline__ __half f2h(float f) { return __float2half(f); }

// Compile-time tile sizes.
constexpr int BLOCK_M = 32;   // rows of Q processed per CTA
constexpr int BLOCK_D = 64;   // chunk of head-dim processed at a time
constexpr int THREADS = 256;  // threads per block
constexpr int MAX_ACC = 64;   // upper bound of (BLOCK_M*N)/THREADS per thread

__global__ void attention_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    float scale)
{
    int b = blockIdx.z;
    int h = blockIdx.y;
    int m_tile = blockIdx.x;
    int m_base = m_tile * BLOCK_M;

    int64_t bh_stride = (int64_t)N * D;
    int64_t bh_idx = (int64_t)b * H + h;

    const __half* Qptr = Q + bh_idx * bh_stride;
    const __half* Kptr = K + bh_idx * bh_stride;
    const __half* Vptr = V + bh_idx * bh_stride;
    __half* Optr = O + bh_idx * bh_stride;

    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));

    extern __shared__ unsigned char smem_raw[];
    __half* Qs_ptr  = reinterpret_cast<__half*>(smem_raw);
    __half* KVs_ptr = Qs_ptr + BLOCK_M * BLOCK_D;
    float*  S_ptr   = reinterpret_cast<float*>(KVs_ptr + (size_t)N * BLOCK_D);

    auto sQ  = make_tensor(make_smem_ptr(Qs_ptr),  make_shape(Int<BLOCK_M>{}, Int<BLOCK_D>{}), make_stride(Int<BLOCK_D>{}, Int<1>{}));
    auto sKV = make_tensor(make_smem_ptr(KVs_ptr), make_shape(N, Int<BLOCK_D>{}), make_stride(Int<BLOCK_D>{}, Int<1>{}));
    auto sS  = make_tensor(make_smem_ptr(S_ptr),   make_shape(Int<BLOCK_M>{}, N), make_stride(N, Int<1>{}));

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    int total_s_elems = BLOCK_M * N;
    int elems_per_thread_s = total_s_elems / nthreads;

    float acc[MAX_ACC];
    #pragma unroll
    for (int i = 0; i < MAX_ACC; ++i) acc[i] = 0.0f;

    int num_dchunks = D / BLOCK_D;

    // ---- Pass 1: S = Q @ K^T (accumulated over head-dim chunks) ----
    for (int c = 0; c < num_dchunks; ++c) {
        int d0 = c * BLOCK_D;

        int qelems2 = (BLOCK_M * BLOCK_D) / 2;
        const __half2* Qptr2 = reinterpret_cast<const __half2*>(Qptr);
        __half2* Qs2 = reinterpret_cast<__half2*>(Qs_ptr);
        for (int idx = tid; idx < qelems2; idx += nthreads) {
            int m = idx / (BLOCK_D / 2);
            int dl2 = idx % (BLOCK_D / 2);
            int gidx = ((m_base + m) * D + d0) / 2 + dl2;
            Qs2[m * (BLOCK_D / 2) + dl2] = Qptr2[gidx];
        }
        int kelems2 = (N * BLOCK_D) / 2;
        const __half2* Kptr2 = reinterpret_cast<const __half2*>(Kptr);
        __half2* KVs2 = reinterpret_cast<__half2*>(KVs_ptr);
        for (int idx = tid; idx < kelems2; idx += nthreads) {
            int n = idx / (BLOCK_D / 2);
            int dl2 = idx % (BLOCK_D / 2);
            int gidx = (n * D + d0) / 2 + dl2;
            KVs2[n * (BLOCK_D / 2) + dl2] = Kptr2[gidx];
        }
        __syncthreads();

        for (int i = 0; i < elems_per_thread_s && i < MAX_ACC; ++i) {
            int idx = tid + i * nthreads;
            if (idx >= total_s_elems) continue;
            int m = idx / N;
            int n = idx % N;
            const float4* qrow4 = reinterpret_cast<const float4*>(Qs_ptr + m * BLOCK_D);
            const float4* krow4 = reinterpret_cast<const float4*>(KVs_ptr + n * BLOCK_D);
